import{_ as l,B as s,c as p,j as i,a as h,G as e,w as o,a5 as r,o as d}from"./chunks/framework.mFcBg5UA.js";const M=JSON.parse('{"title":"浏览器渲染的基石：DOM Tree 与 CSSOM","titleTemplate":"前端知识图谱","description":"","frontmatter":{"outline":"deep","title":"浏览器渲染的基石：DOM Tree 与 CSSOM","titleTemplate":"前端知识图谱","head":[["link",{"rel":"canonical","href":"https://luffy-d-lufei.github.io/my-blog/feMap/browser/dom-cssom.html"}]]},"headers":[],"relativePath":"feMap/browser/dom-cssom.md","filePath":"feMap/browser/dom-cssom.md","lastUpdated":1725973729000}'),c={name:"feMap/browser/dom-cssom.md"};function k(m,a,g,E,u,b){const n=s("Graph"),t=s("ClientOnly");return d(),p("div",null,[a[0]||(a[0]=i("h1",{id:"浏览器渲染的基石-dom-tree-与-cssom",tabindex:"-1"},[h("浏览器渲染的基石：DOM Tree 与 CSSOM "),i("a",{class:"header-anchor",href:"#浏览器渲染的基石-dom-tree-与-cssom","aria-label":'Permalink to "浏览器渲染的基石：DOM Tree 与 CSSOM"'},"​")],-1)),e(t,null,{default:o(()=>[e(n,{type:"domAndCssom"})]),_:1}),a[1]||(a[1]=r(`<p>大家好，我是徐徐。今天我们聊聊浏览器渲染的基石：DOM Tree 与 CSSOM 。</p><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>在现代 Web 开发中，理解浏览器如何解析和渲染网页至关重要。这个过程的核心就是 DOM（Document Object Model）树和 CSSOM（CSS Object Model）的构建和交互。本文将探讨这两个关键概念，揭示它们如何共同工作以创建我们在屏幕上看到的网页。</p><h2 id="dom-树-document-object-model-tree" tabindex="-1">DOM 树（Document Object Model Tree） <a class="header-anchor" href="#dom-树-document-object-model-tree" aria-label="Permalink to &quot;DOM 树（Document Object Model Tree）&quot;">​</a></h2><h3 id="定义和基本概念" tabindex="-1">定义和基本概念 <a class="header-anchor" href="#定义和基本概念" aria-label="Permalink to &quot;定义和基本概念&quot;">​</a></h3><p>DOM 树是 HTML 文档的内存表示，它将文档结构化为一个逻辑树。每个 HTML 元素、属性和文本片段都成为树中的一个节点。DOM 提供了一个编程接口，允许开发者通过脚本语言（如 JavaScript）动态地访问和操作网页内容和结构。</p><h3 id="dom-树的形成过程" tabindex="-1">DOM 树的形成过程 <a class="header-anchor" href="#dom-树的形成过程" aria-label="Permalink to &quot;DOM 树的形成过程&quot;">​</a></h3><p><img src="https://cdn.nlark.com/yuque/0/2024/png/277039/1725033475856-16bf53e7-e266-45d5-813e-84bd5b185f00.png#averageHue=%23fcfcfc&amp;clientId=u2e228c52-f402-4&amp;from=paste&amp;height=1010&amp;id=u35ea6486&amp;originHeight=1262&amp;originWidth=615&amp;originalType=binary&amp;ratio=1.25&amp;rotation=0&amp;showTitle=false&amp;size=99869&amp;status=done&amp;style=none&amp;taskId=uc419d35d-6deb-4654-9b35-423c18990cb&amp;title=&amp;width=492" alt=""></p><ol><li><strong>字节流解析</strong> ：浏览器从服务器接收 HTML 文件的字节流。</li><li><strong>字符识别</strong>：将字节流转换为字符。</li><li><strong>令牌化</strong>：将字符串转换为定义的令牌（如 、 等）。</li><li><strong>节点生成</strong>：根据令牌创建节点。</li><li><strong>DOM 树构建</strong>：将节点连接成一个树状结构。</li></ol><p>例如，考虑以下 HTML：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">html</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">head</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; 示例页面 &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">head</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; 欢迎 &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; 这是一个段落。&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">html</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>这段 HTML 将被解析成如下的 DOM 树结构：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Document</span></span>
<span class="line"><span>└── html</span></span>
<span class="line"><span>    ├── head</span></span>
<span class="line"><span>    │   └── title</span></span>
<span class="line"><span>    │       └── #text: 示例页面</span></span>
<span class="line"><span>    └── body</span></span>
<span class="line"><span>        ├── h1</span></span>
<span class="line"><span>        │   └── #text: 欢迎</span></span>
<span class="line"><span>        └── p</span></span>
<span class="line"><span>            └── #text: 这是一个段落。</span></span></code></pre></div><h3 id="dom-树的内部结构" tabindex="-1">DOM 树的内部结构 <a class="header-anchor" href="#dom-树的内部结构" aria-label="Permalink to &quot;DOM 树的内部结构&quot;">​</a></h3><p>每个 DOM 节点通常包含以下信息：</p><ul><li>nodeType（节点类型，如元素、文本、注释等）</li><li>nodeName（节点名称）</li><li>nodeValue（节点值）</li><li>parentNode（父节点）</li><li>childNodes（子节点列表）</li><li>attributes（属性列表，仅适用于元素节点）</li></ul><h3 id="dom-操作的性能考虑" tabindex="-1">DOM 操作的性能考虑 <a class="header-anchor" href="#dom-操作的性能考虑" aria-label="Permalink to &quot;DOM 操作的性能考虑&quot;">​</a></h3><p>频繁的 DOM 操作可能导致性能问题，因为每次修改都可能触发重排（reflow）或重绘（repaint）。为提高性能，可以：</p><ul><li>使用文档片段（DocumentFragment）批量操作 DOM。</li><li>离线操作 DOM（如先从 DOM 树上移除元素，修改后再插入）。</li><li>使用虚拟 DOM 技术（如 React 和 Vue 采用的方法）。</li></ul><h2 id="cssom-css-object-model" tabindex="-1">CSSOM（CSS Object Model） <a class="header-anchor" href="#cssom-css-object-model" aria-label="Permalink to &quot;CSSOM（CSS Object Model）&quot;">​</a></h2><h3 id="cssom-的定义和作用" tabindex="-1">CSSOM 的定义和作用 <a class="header-anchor" href="#cssom-的定义和作用" aria-label="Permalink to &quot;CSSOM 的定义和作用&quot;">​</a></h3><p>CSSOM 是 CSS 的对象表示，它将样式信息转换为浏览器可以理解和处理的结构。CSSOM 与 DOM 树并行构建，最终合并形成渲染树。</p><h3 id="cssom-的构建过程" tabindex="-1">CSSOM 的构建过程 <a class="header-anchor" href="#cssom-的构建过程" aria-label="Permalink to &quot;CSSOM 的构建过程&quot;">​</a></h3><p><img src="https://cdn.nlark.com/yuque/0/2024/png/277039/1725033650616-835e00f9-3186-4924-a2ba-adde30d726b2.png#averageHue=%23f3f2f7&amp;clientId=u2e228c52-f402-4&amp;from=paste&amp;height=842&amp;id=u74e89d9f&amp;originHeight=1052&amp;originWidth=365&amp;originalType=binary&amp;ratio=1.25&amp;rotation=0&amp;showTitle=false&amp;size=73536&amp;status=done&amp;style=none&amp;taskId=u94c0c797-b0c3-4859-91c7-4682770c285&amp;title=&amp;width=292" alt=""></p><ol><li><strong>字节流解析</strong> ：与 HTML 类似，CSS 文件首先被解析为字节流。</li><li><strong>字符识别</strong>：将字节流转换为字符。</li><li><strong>令牌化</strong> ：将字符串转换为定义的令牌（如选择器、属性、值等）。</li><li><strong>节点生成</strong> ：根据令牌创建 CSSOM 节点。</li><li><strong>CSSOM 树构建</strong> ：将节点连接成树状结构，计算样式。</li></ol><h3 id="cssom-的内部结构" tabindex="-1">CSSOM 的内部结构 <a class="header-anchor" href="#cssom-的内部结构" aria-label="Permalink to &quot;CSSOM 的内部结构&quot;">​</a></h3><p>CSSOM 以树状结构组织样式信息，类似于 DOM 树。每个节点包含对应元素的计算样式。例如：</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">font-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">blue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">margin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">px</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;}</span></span></code></pre></div><p>可能形成如下 CSSOM 结构：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CSSOM</span></span>
<span class="line"><span>└── body</span></span>
<span class="line"><span>    ├── font-size: 16px</span></span>
<span class="line"><span>    ├── h1</span></span>
<span class="line"><span>    │   └── color: blue</span></span>
<span class="line"><span>    └── p</span></span>
<span class="line"><span>        └── margin: 10px</span></span></code></pre></div><h3 id="cssom-对渲染性能的影响" tabindex="-1">CSSOM 对渲染性能的影响 <a class="header-anchor" href="#cssom-对渲染性能的影响" aria-label="Permalink to &quot;CSSOM 对渲染性能的影响&quot;">​</a></h3><p>CSSOM 的构建是渲染阻塞的，意味着在 CSSOM 完全构建之前，页面不会被渲染。为优化性能：</p><ul><li>精简 CSS，移除未使用的样式。</li><li>使用媒体查询，使非关键 CSS 异步加载。</li><li>考虑内联关键 CSS。</li></ul><h2 id="dom-树和-cssom-的关系" tabindex="-1">DOM 树和 CSSOM 的关系 <a class="header-anchor" href="#dom-树和-cssom-的关系" aria-label="Permalink to &quot;DOM 树和 CSSOM 的关系&quot;">​</a></h2><p><img src="https://cdn.nlark.com/yuque/0/2024/png/277039/1725034830749-07ba0247-c188-4b96-a650-f77dc9e341bb.png#averageHue=%23d0d4eb&amp;clientId=u2e228c52-f402-4&amp;from=paste&amp;id=u07f5fb32&amp;originHeight=591&amp;originWidth=1181&amp;originalType=url&amp;ratio=1.25&amp;rotation=0&amp;showTitle=false&amp;status=done&amp;style=none&amp;taskId=u8cf98316-91ba-4833-9357-c7bae9c2d3a&amp;title=" alt=""></p><h3 id="并行构建" tabindex="-1">并行构建 <a class="header-anchor" href="#并行构建" aria-label="Permalink to &quot;并行构建&quot;">​</a></h3><p>DOM 树和 CSSOM 是并行构建的，但它们相互依赖以创建最终的渲染输出。</p><h3 id="渲染树-render-tree-的形成" tabindex="-1">渲染树（Render Tree）的形成 <a class="header-anchor" href="#渲染树-render-tree-的形成" aria-label="Permalink to &quot;渲染树（Render Tree）的形成&quot;">​</a></h3><p>渲染树结合了 DOM 树和 CSSOM：</p><ol><li>遍历 DOM 树中的可见节点。</li><li>对每个可见节点，从 CSSOM 中找到对应的样式规则并应用。</li><li>输出包含内容和样式的渲染树。</li></ol><h3 id="javascript-对-dom-和-cssom-的影响" tabindex="-1">JavaScript 对 DOM 和 CSSOM 的影响 <a class="header-anchor" href="#javascript-对-dom-和-cssom-的影响" aria-label="Permalink to &quot;JavaScript 对 DOM 和 CSSOM 的影响&quot;">​</a></h3><p>JavaScript 可以动态修改 DOM 和 CSSOM，但这可能导致额外的回流和重绘，影响性能。现代框架（如 React）通过虚拟 DOM 等技术优化了这一过程。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>深入理解 DOM 树和 CSSOM 不仅有助于我们编写更高效的 Web 应用，还能帮助我们更好地理解和优化 Web 性能。随着 Web 技术的不断发展，保持对这些核心概念的深入理解将使我们能够更好地适应未来的变化和挑战。</p><p>虽然我们在日常的开发中可能不会去深入探究它们，但是如果遇到一些棘手的问题也是可以朝着这个方向去研究的。如果你有其他的想法欢迎和我交流。</p>`,45))])}const y=l(c,[["render",k]]);export{M as __pageData,y as default};
